            VertexGlslEs,
            VertexGlsl330),
        new ShaderStageSources(
            PixelSpirv,
            PixelHlsl,
            PixelMsl,
            PixelGlsl,
            PixelGlslEs,
            PixelGlsl330),
        new ShaderReflection
        {
            Uniforms = new UniformParam[]
            {
                new("transformMat", 0, 64, UniformType.Matrix4x4),
                new("scissorMat", 64, 64, UniformType.Matrix4x4),
                new("paintMat", 128, 64, UniformType.Matrix4x4),
                new("innerCol", 192, 16, UniformType.Vector4),
                new("outerCol", 208, 16, UniformType.Vector4),
                new("scissorExt", 224, 8, UniformType.Vector2),
                new("scissorScale", 232, 8, UniformType.Vector2),
                new("extent", 240, 8, UniformType.Vector2),
                new("radius", 248, 4, UniformType.Float),
                new("feather", 252, 4, UniformType.Float),
                new("strokeMult", 256, 4, UniformType.Float),
                new("strokeThr", 260, 4, UniformType.Float),
            },
            Textures = new ResourceBinding[]
            {
                new("g_texture", 0),
            },
            Samplers = new ResourceBinding[]
            {
                new("g_textureSampler", 0),
            },
        }
    );
}


/// <summary>
/// Resolves this program's uniform and texture slots against its own reflection.
/// Call once when the program is created - not per frame or per draw - and reuse the
/// result, since slots are stable for the program's lifetime.
/// </summary>
internal readonly struct NvgTrianglesParameters
{
    internal NvgTrianglesParameters(ShaderReflection reflection)
    {
        transformMat = new Float4x4EffectParameter(SlotOf(reflection, "transformMat"));
        scissorMat = new Float4x4EffectParameter(SlotOf(reflection, "scissorMat"));
        paintMat = new Float4x4EffectParameter(SlotOf(reflection, "paintMat"));
        innerCol = new Float4EffectParameter(SlotOf(reflection, "innerCol"));
        outerCol = new Float4EffectParameter(SlotOf(reflection, "outerCol"));
        scissorExt = new Float2EffectParameter(SlotOf(reflection, "scissorExt"));
        scissorScale = new Float2EffectParameter(SlotOf(reflection, "scissorScale"));
        extent = new Float2EffectParameter(SlotOf(reflection, "extent"));
        radius = new FloatEffectParameter(SlotOf(reflection, "radius"));
        feather = new FloatEffectParameter(SlotOf(reflection, "feather"));
        strokeMult = new FloatEffectParameter(SlotOf(reflection, "strokeMult"));
        strokeThr = new FloatEffectParameter(SlotOf(reflection, "strokeThr"));
        g_texture = new TextureEffectParameter(TextureSlotOf(reflection, "g_texture"));
    }

    public Float4x4EffectParameter transformMat { get; }
    public Float4x4EffectParameter scissorMat { get; }
    public Float4x4EffectParameter paintMat { get; }
    public Float4EffectParameter innerCol { get; }
    public Float4EffectParameter outerCol { get; }
    public Float2EffectParameter scissorExt { get; }
    public Float2EffectParameter scissorScale { get; }
    public Float2EffectParameter extent { get; }
    public FloatEffectParameter radius { get; }
    public FloatEffectParameter feather { get; }
    public FloatEffectParameter strokeMult { get; }
    public FloatEffectParameter strokeThr { get; }
    public TextureEffectParameter g_texture { get; }

    // -1 ("not found") mirrors the old FNA model's "parameter != null" check for a
    // uniform the HLSL compiler optimized out - every *EffectParameter.SetValue below
    // no-ops on a negative slot.
    private static int SlotOf(ShaderReflection reflection, string name)
    {
        foreach (var uniform in reflection.Uniforms)
        {
            if (uniform.Name == name) return uniform.Offset;
        }
        return -1;
    }

    private static int TextureSlotOf(ShaderReflection reflection, string name)
    {
        foreach (var texture in reflection.Textures)
        {
            if (texture.Name == name) return texture.Slot;
        }
        return -1;
    }
}

internal sealed record NvgTrianglesProgram(
    ShaderStageSources Vertex,
    ShaderStageSources Pixel,
    ShaderReflection Reflection)
{
    public ReadOnlyMemory<byte> VertexSpirv => Vertex.Spirv;
    public ReadOnlyMemory<byte> PixelSpirv => Pixel.Spirv;

    public NvgTrianglesParameters Bind() => new(Reflection);
}
